def mk(s,new,reviews,ids,speed=False):
 q,a=base.qa(s['items'],ids); text=text_of(s)
 return {'id':s['id'],'language':'fr','cefr':'B2','unit':3,'sequence':s['sequence'],'revision':1,'title':s['title'],'passage_type':s['ptype'],'genre':s['genre'],'domains':s['domains'],'topics':s['topics'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':new,'review_lexical_targets':reviews,'grammar_targets':s['grammar'],'discourse_targets':s['discourse'],'questions':q,'answer_key':a,'speed_training':{'timed':speed,'benchmark_eligible':speed,'comprehension_gate':0.8,'new_word_policy':'none' if speed else 'controlled','notes':'French B2 Unit 03 guarded production batch.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['Guarded French B2 Unit 03: ethics and competing values.','Accepted B2 default of four fresh targets per P01-P05; P06 zero new.','All scenarios are fictional or generic; no external factual claim is required.']},'paired_text_group':None,'prerequisites':['French B2 Units 01-02 canonical and Unit02 frontier lock PASS'],'difficulty_notes_internal':'B2 ethical reasoning: competing values, scope, exceptions, stakeholder harm, counterargument and revisability.','reader_tags':['unit_role:'+s['ptype'],'generation_batch','french_b2_u03']}

def build(a1,a2,b1,b2,deck):
 prior=base.prior(a1+a2+b1+b2); prior_ids={t.get('id') for r in a1+a2+b1+b2 for t in r.get('new_lexical_targets',[]) if isinstance(t,dict)}; prior_forms={t.get('form') for r in a1+a2+b1+b2 for t in r.get('new_lexical_targets',[]) if isinstance(t,dict)}; bad=[]
 for f in FORMS:
  if f not in deck: bad.append(f+':missing_lexicon')
  elif base.tid(deck[f]['rank']) in prior_ids or f in prior_forms or prior.get(f): bad.append(f+':already_deliberate')
 if bad: raise AssertionError('B2 Unit03 candidate failures: '+', '.join(bad))
 out=[]
 for s in SPECS:
  text=text_of(s); new=[base.nt(f,text,deck) for f in s['forms']]; reviews=[base.rev(f,prior) for f in s['reviews']]; ids={t['form']:t['id'] for t in new+reviews}; out.append(mk(s,new,reviews,ids))
 reviews=[base.cur(f,deck) for f in FORMS]; ids={t['form']:t['id'] for t in reviews}; out.append(mk(CHECKPOINT,[],reviews,ids,True)); return out

