 if [r['sequence'] for r in unit]!=list(range(13,19)) or [r['id'] for r in unit]!=[f'fr-b2-u03-p{i:02d}' for i in range(1,7)]: raise AssertionError('B2 Unit03 sequence/id continuity failure')
